krpano.action:
var el = caller.sprite; 

if(el) {
    el.style.boxSizing = "border-box";

    // CSS가 적용되면 XML의 bgalpha="0.3" 대신 이 스타일이 보입니다.
    el.style.background = "rgba(255, 255, 255, 0.15)";
    el.style.backdropFilter = "blur(12px)";
    el.style.webkitBackdropFilter = "blur(12px)";

    // !important로 강제 적용하여 krpano XML 속성을 이깁니다.
    el.style.setProperty("border-radius", "50px", "important");
    el.style.setProperty("border", "2px solid rgba(255, 255, 255, 0.5)", "important");

    el.style.boxShadow = "0 10px 30px rgba(0, 0, 0, 0.2)";
    el.style.transition = "background 0.3s, border-color 0.3s, box-shadow 0.3s";

    el.style.display = "flex";
    el.style.alignItems = "center";
    el.style.justifyContent = "center";
    el.style.overflow = "hidden"; 

    el.style.userSelect = "none";
    el.style.cursor = "pointer";
    el.style.transformStyle = "preserve-3d";
}

var el = caller.sprite;
var isHover = args[0]; 

if(el) {
    if(isHover == true || isHover == "true") {
        el.style.background = "rgba(255, 255, 255, 0.35)";
        el.style.setProperty("border", "2px solid rgba(255, 255, 255, 1.0)", "important");
        el.style.boxShadow = "0 20px 50px rgba(255, 255, 255, 0.4)";
    } else {
        el.style.background = "rgba(255, 255, 255, 0.15)";
        el.style.setProperty("border", "2px solid rgba(255, 255, 255, 0.5)", "important");
        el.style.boxShadow = "0 10px 30px rgba(0, 0, 0, 0.2)";
    }
}

scene.action:

// 1. krpano 레이어 보이기
krpano.set("layer[dashboard_ui_layer].visible", true);

// 2. 초기화 함수가 존재하는지 확인 후 실행 (안전장치)
if (typeof window.init_and_reset_ui === 'function') {
    window.init_and_reset_ui();
}


var layer = caller.sprite;

// ---------------------------------------------------------
// 1. CSS 스타일 정의
// ---------------------------------------------------------
var cssStyles = `
    :root {
        --color1-rgb: 30, 30, 30;
        --color2-rgb: 255, 255, 255;
        --color3-rgb: 255, 255, 255;
        --fade-out-duration: 0.4s;
    }
    [data-theme="darkmode"] { --color1-rgb: 30, 30, 30; --color2-rgb: 100, 100, 100; --color3-rgb: 200, 200, 200; }
    [data-theme="blue"] { --color1-rgb: 200, 200, 255; --color2-rgb: 0, 0, 128; --color3-rgb: 0, 0, 10; }

    .ui-wrapper {
        width: 100%; height: 100%;
        display: flex; justify-content: center; align-items: center;
        font-family: 'Helvetica Neue', Arial, sans-serif;
        pointer-events: none;
    }

    .dashboard-container, .control-bar, .global-backdrop { pointer-events: auto; }

    .global-backdrop {
        position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
        background: rgba(255, 255, 255, 0.1);
        backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
        z-index: 2; transition: opacity var(--fade-out-duration) ease-out; opacity: 1;
    }

    .dashboard-container {
        position: relative; 
        width: 950px; height: 600px;
        display: flex; flex-direction: row;
        background: rgba(var(--color3-rgb), 0.3);
        border: 1px solid rgba(var(--color1-rgb), 0.1);
        border-radius: 40px;
        box-shadow: 0 30px 60px rgba(0, 0, 0, 0.6);
        backdrop-filter: blur(25px); -webkit-backdrop-filter: blur(25px);
        z-index: 5; overflow: hidden;
        transition: opacity var(--fade-out-duration) ease-out; opacity: 1;
    }

    .dashboard-bg {
        position: absolute; top: 0; left: 0; width: 100%; height: 100%;
        background-size: cover; background-position: center; background-repeat: no-repeat;
        transition: none; z-index: 0;
    }

    .content-area {
        position: relative; z-index: 1; flex: 1; padding: 30px 40px;
        display: flex; flex-direction: column; justify-content: flex-start; overflow-y: auto;
    }
    .content-area::-webkit-scrollbar, .character-container::-webkit-scrollbar { display: none; }

    .content-header { text-align: center; }
    .content-header h3 { margin: 20px 0 0 0; font-size: 24px; font-weight: 600; color: rgba(255,155,40,1); }
    .content-header p { margin: 0 0 30px 0; font-size: 14px; color: rgba(var(--color1-rgb), 0.6); }

    .character-container, .gender-container {
        display: flex; gap: 40px; align-items: center; justify-content: center;
        padding: 40px 40px 110px 40px; width: 100%; flex: 1;
        overflow-x: visible; box-sizing: border-box;
    }

    .character-card, .gender-card {
        width: 260px; height: 260px;
        background: rgba(var(--color2-rgb), 0.25);
        border: 1px solid rgba(var(--color1-rgb), 0.4);
        border-radius: 30px; display: flex; flex-direction: column;
        overflow: hidden; cursor: pointer; transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
        position: relative; box-sizing: border-box; flex-shrink: 0;
        box-shadow: 0 5px 10px rgba(0, 0, 0, 0.3);
    }
    .character-card:hover, .gender-card:hover {
        transform: translateY(-5px) scale(1.05); opacity: 1;
        background: rgba(var(--color2-rgb), 0.25);
        border: 1px solid rgba(var(--color1-rgb), 0.5);
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
    }
    .character-card.selected, .gender-card.selected {
        transform: translateY(-10px) scale(1.1) !important;
        border: 4px solid #ff7052;
        box-shadow: 0 0 40px rgba(255, 112, 82, 0.6), 0 20px 40px rgba(0, 0, 0, 0.4);
        z-index: 20;
    }

    .card-image-placeholder {
        flex: 1; width: 100%; display: flex; justify-content: center; align-items: flex-end;
        padding-bottom: 20px; font-size: 50px; color: rgba(var(--color1-rgb), 0.8);
    }
    .card-info {
        height: auto; width: 100%; padding: 0 0 40px 0;
        display: flex; flex-direction: column; justify-content: flex-start; align-items: center;
    }
    .card-info h4 { margin: 0; color: rgba(0, 0, 0, 1); font-size: 24px; font-weight: 800; line-height: 1.2; }
    .card-info p { margin: 5px 0 0 0; color: #5c5c5c; font-size: 16px; font-weight: 400; }

    .select-button {
        width: 140px; height: 50px; display: flex; justify-content: center; align-items: center;
        font-size: 16px; font-weight: 500; color: rgba(var(--color1-rgb), 1); letter-spacing: 0.5px;
        background: rgba(245,245,245, 0.3); border: 1px solid rgba(var(--color1-rgb), 0.5);
        border-radius: 100px; cursor: pointer; user-select: none; transition: all 0.3s ease;
        backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px);
    }
    .select-button:hover {
        background: rgba(245,245,245, 0.6); border-color: rgba(var(--color1-rgb), 0.6);
        transform: translateY(-2px); box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
    }
    .select-button.selected { 
        background: rgba(var(--color1-rgb), 1); color: #fff;
        border: 1px solid rgba(var(--color1-rgb), 1); box-shadow: 0 0 20px rgba(var(--color1-rgb), 0.4);
        transform: translateY(-5px) scale(1.05); font-weight: bold;
    }
    .select-button:active { transform: scale(0.95); }

    .start-button { width: 120px; background: rgba(245,245,245, 0.3); }
    .start-button.disabled { background: rgba(var(--color1-rgb), 0.2) !important; color: rgba(var(--color1-rgb), 0.4) !important; cursor: not-allowed; }

    .control-bar {
        position: absolute; bottom: 30px; left: 50%; transform: translateX(-50%);
        display: flex; gap: 25px; padding: 12px 30px;
        background: rgba(var(--color2-rgb), 0.15); border: 1px solid rgba(var(--color1-rgb), 0.2);
        border-radius: 50px; box-shadow: 0 8px 32px 0 rgba(var(--color3-rgb), 0.3);
        backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); z-index: 10;
    }
    .icon-btn {
        color: rgba(var(--color1-rgb), 0.8); font-size: 24px; cursor: pointer; transition: all 0.3s ease;
        user-select: none; display: flex; align-items: center; justify-content: center; width: 30px; height: 30px;
    }
    .icon-btn:hover { color: rgba(var(--color1-rgb), 1); text-shadow: 0 0 10px rgba(var(--color1-rgb), 0.6); transform: scale(1.2); }
    .icon-btn:active { transform: scale(0.95); }

    .progress-bar-container { display: flex; align-items: flex-start; justify-content: center; margin-bottom: 40px; height: 40px; }
    .step-item { display: flex; flex-direction: column; align-items: center; position: relative; width: 40px; }
    .step-circle {
        width: 14px; height: 14px; border-radius: 50%; border: 2px solid rgba(var(--color1-rgb), 0.3);
        background: transparent; margin-bottom: 8px; position: relative; z-index: 2; transition: all 0.3s;
    }
    .step-text { font-size: 11px; color: rgba(var(--color1-rgb), 0.4); font-weight: 500; white-space: nowrap; position: absolute; top: 22px; }

    .step-item.active .step-circle { border-color: rgba(var(--color1-rgb), 1); background: transparent; }
    .step-item.active .step-circle::after {
        content: ""; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
        width: 6px; height: 6px; border-radius: 50%; background: rgba(var(--color1-rgb), 1);
    }
    .step-item.active .step-text { color: rgba(var(--color1-rgb), 1); font-weight: 800; }

    .step-item.completed .step-circle { background: rgba(var(--color1-rgb), 0.6); border-color: rgba(var(--color1-rgb), 0.6); }
    .step-item.completed .step-text { color: rgba(var(--color1-rgb), 0.6); }

    .step-line { width: 80px; height: 1px; background: rgba(var(--color1-rgb), 0.2); margin: 0 5px; margin-top: 7px; }
`;

var styleElem = document.createElement("style");
styleElem.innerHTML = cssStyles;
document.head.appendChild(styleElem);


// ---------------------------------------------------------
// 2. HTML 구조 정의 (수정됨)
// ---------------------------------------------------------
var htmlContent = `
<div class="ui-wrapper">
    <div id="global_backdrop" class="global-backdrop"></div>

    <div id="dashboard_panel" class="dashboard-container">
        <div id="dashboard_bg" class="dashboard-bg"></div>

        <div class="content-area">
            <div id="selection_view" style="display: flex; height: 100%; flex-direction: column; align-items: center; position: relative">
                <div class="content-header" style="margin-bottom: 30px">
                    <div class="progress-bar-container" id="selection_progress_bar"></div>
                    <h3 id="selection_title">Title Here</h3>
                </div>

                <div id="selection_card_container" class="gender-container" style="overflow-x: visible; padding: 40px 40px 110px 40px"></div>

                <div style="position: absolute; bottom: 0; margin-bottom: 10px; display: flex; gap: 20px; justify-content: center; width: 100%;">
                    <div id="btn_back" class="select-button" onclick="window.handleBack()" ontouchend="window.handleBack()" >이전</div>
                    <div id="btn_next" class="select-button start-button disabled" onclick="window.handleNext()" ontouchend="window.handleNext()">다음</div>
                </div>
            </div>

            <div id="profile_view" style="display: none; height: 100%; flex-direction: column; position: relative; align-items: center">
                <div class="content-header" style="margin-bottom: 30px">
                    <div class="progress-bar-container" id="profile_progress_bar"></div>
                    <h3 id="title_profile">파트너 프로필</h3>
                </div>

                <div class="profile-content" style="flex: 1; display: flex; justify-content: center; align-items: center; width: 100%">
                    </div>

                <div style="position: absolute; bottom: 0; margin-bottom: 10px; display: flex; gap: 20px; justify-content: center; width: 100%;">
                    <div class="select-button" onclick="window.showSelectionStep(4)" ontouchend="window.showSelectionStep(4)">이전</div>
                    <div class="select-button start-button" onclick="window.startRealTour()" ontouchend="window.startRealTour()">시작</div>
                </div>
            </div>
        </div>
    </div>
    <!--
    <div class="control-bar">
        <div class="icon-btn" title="Previous Scene" onclick="window.ui_trace('Load Previous Scene')" ontouchend="window.ui_trace('Load Previous Scene')">◀</div>
        <div class="icon-btn" title="Zoom In" onclick="window.ui_trace('Zoom In')" ontouchend="window.ui_trace('Zoom In')">⊕</div>
        <div class="icon-btn" title="Zoom Out" onclick="window.ui_trace('Zoom Out')" ontouchend="window.ui_trace('Zoom Out')">⊖</div>
        <div class="icon-btn" title="Next Scene" onclick="window.ui_trace('Load Next Scene')" ontouchend="window.ui_trace('Load Next Scene')">▶</div>
        <div class="icon-btn" title="Fullscreen" onclick="window.ui_trace('Toggle Fullscreen')" ontouchend="window.ui_trace('Toggle Fullscreen')">⛶</div>
    </div>
    -->
</div>
`;

layer.innerHTML = htmlContent;


// ---------------------------------------------------------
// 3. 로직 처리 (JS)
// ---------------------------------------------------------
var selectedCharacter = null;
var userGender = null;
var currentStep = 1;

// Constants
var STEP_START = 1;
var STEP_INTRO_VIDEO = 2;
var STEP_GENDER = 3;
var STEP_PARTNER = 4;
var STEP_PROFILE = 5;
var FADE_DURATION_MS = 400;

window.init_and_reset_ui = function() {

    selectedCharacter = null;
    userGender = null;
    currentStep = STEP_START;

    var panel = document.getElementById('dashboard_panel');
    var backdrop = document.getElementById('global_backdrop');

    if(panel) {
        panel.style.display = 'flex';
        panel.style.opacity = '1';
        panel.style.background = "rgba(42, 42, 42, 0.6)";
        panel.style.border = "1px solid rgba(255, 255, 255, 0.1)";
    }
    if(backdrop) {
        backdrop.style.display = 'block';
        backdrop.style.opacity = '1';
    }

    window.showSelectionStep(STEP_START);
};

window.ui_trace = function(msg) {
    krpano.trace(0, "[Dashboard UI] " + msg);
    if(msg === 'Zoom In') krpano.call("adjusthlookat(0); moveto(get(view.hlookat), get(view.vlookat), calc(view.fov - 10));");
    if(msg === 'Zoom Out') krpano.call("adjusthlookat(0); moveto(get(view.hlookat), get(view.vlookat), calc(view.fov + 10));");
    if(msg === 'Toggle Fullscreen') krpano.call("switch(fullscreen);");
};

// [수정된 함수] 프로그래스 바 로직과 뷰 전환 로직 순서 변경
window.showSelectionStep = function(step) {
    currentStep = step;

    // 1. 프로그래스 바 HTML 생성 (뷰 전환 전에 먼저 계산)
    var barHTML = "";
    var barContainerSelection = document.getElementById("selection_progress_bar");
    var barContainerProfile = document.getElementById("profile_progress_bar"); // [추가] Profile쪽 컨테이너
    var panel = document.getElementById("dashboard_panel");

    // 스타일 및 표시 여부 결정
    if (step < STEP_GENDER) {
        // Intro 단계
        if(barContainerSelection) barContainerSelection.style.display = "none";
        if(panel) {
            panel.style.background = "rgba(42, 42, 42, 0.6)";
            panel.style.border = "1px solid rgba(255, 255, 255, 0.1)";
        }
    } else {
        // 선택 단계 & 프로필 단계
        if(barContainerSelection) barContainerSelection.style.display = "flex";
        if(panel) {
            panel.style.background = ""; // Glass Default
            panel.style.border = "";
        }

        // 클래스 계산
        var isGenderDone = step > STEP_GENDER;
        var isPartnerDone = step > STEP_PARTNER;

        var classGender = isGenderDone ? "completed" : (step === STEP_GENDER ? "active" : "");
        var classPartner = isPartnerDone ? "completed" : (step === STEP_PARTNER ? "active" : "");
        var classProfile = step === STEP_PROFILE ? "active" : "";

        var line1Style = step >= STEP_PARTNER ? "0.6" : "0.2";
        var line2Style = step >= STEP_PROFILE ? "0.6" : "0.2";

        barHTML = `
            <div class="step-item ${classGender}">
                <div class="step-circle"></div><div class="step-text">성별 설정</div>
            </div>
            <div class="step-line" style="background: rgba(var(--color1-rgb), ${line1Style})"></div>

            <div class="step-item ${classPartner}">
                <div class="step-circle"></div><div class="step-text">파트너 설정</div>
            </div>
            <div class="step-line" style="background: rgba(var(--color1-rgb), ${line2Style})"></div>

            <div class="step-item ${classProfile}">
                <div class="step-circle"></div><div class="step-text">프로필 확인</div>
            </div>
        `;
    }

    // 2. 뷰 전환 및 HTML 주입
    var view = document.getElementById("selection_view");
    var profileView = document.getElementById("profile_view");

    if (step === STEP_PROFILE) {
        // 프로필 뷰 활성화
        view.style.display = "none";
        profileView.style.display = "flex";

        // [중요] 프로필 뷰의 진행 바 컨테이너에 HTML 주입
        if(barContainerProfile) barContainerProfile.innerHTML = barHTML;

        showProfileView();
        return; // 여기서 종료 (아래 로직은 Selection 뷰용)
    } else {
        // 일반 뷰 활성화
        view.style.display = "flex";
        profileView.style.display = "none";

        // 일반 뷰의 진행 바 컨테이너에 HTML 주입
        if(barContainerSelection) barContainerSelection.innerHTML = barHTML;
    }

    // 3. Selection View 내부 콘텐츠 렌더링 (Step 1~4)
    var titleEl = document.getElementById("selection_title");
    var headerEl = titleEl ? titleEl.parentElement : document.querySelector("#selection_view .content-header");
    var container = document.getElementById("selection_card_container");
    var backBtn = document.getElementById("btn_back");
    var nextBtn = document.getElementById("btn_next");

    container.innerHTML = ""; // 초기화

    if (step === STEP_START) {
        if (headerEl) headerEl.style.display = "none";
        backBtn.style.display = "none";
        nextBtn.classList.remove("disabled");
        nextBtn.innerText = "START";
        container.innerHTML = `<div style="display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%;"><img src="Img/logo.png" style="max-width: 720px; max-height: 420px; object-fit: contain;" /></div>`;
        updateDashboardBg("");

    } else if (step === STEP_INTRO_VIDEO) {
        if (headerEl) headerEl.style.display = "block";
        titleEl.innerText = "";
        backBtn.style.display = "flex";
        nextBtn.classList.remove("disabled");
        nextBtn.innerText = "다음";
        container.innerHTML = ""; 
        updateDashboardBg("");

    } else if (step === STEP_GENDER) {
        titleEl.innerText = "당신의 성별을 무엇인가요?";
        backBtn.style.display = "flex";
        nextBtn.innerText = "다음";
        if (userGender) nextBtn.classList.remove("disabled");
        else nextBtn.classList.add("disabled");
        updateDashboardBg("Img/bg1.jpg");

        var genders = [{ id: "M", label: "남성", sub: "(Male)", img: "Img/IconM.png" }, { id: "F", label: "여성", sub: "(Female)", img: "Img/IconF.png" }];
        genders.forEach(function(g) {
            var card = document.createElement("div");
            card.className = "gender-card";
            if (userGender === g.id) card.classList.add("selected");
            card.onclick = function() { window.selectGender(g.id, card); };
            card.ontouchend = function() { window.selectGender(g.id, card); };
            card.innerHTML = `<div class="card-image-placeholder"><img src="${g.img}" style="height: 80px; width: auto; object-fit: contain;" /></div><div class="card-info"><h4>${g.label}</h4><p>${g.sub}</p></div>`;
            container.appendChild(card);
            card.style.pointerEvents = 'auto'; // krpano의 터치 방해를 뚫음
            card.style.cursor = 'pointer';
            card.style.zIndex = '1000';
        });



    } else if (step === STEP_PARTNER) {
        titleEl.innerText = "당신의 데이트 상대를 골라주세요.";
        backBtn.style.display = "flex";
        if (selectedCharacter) nextBtn.classList.remove("disabled");
        else nextBtn.classList.add("disabled");
        if (userGender === "M") updateDashboardBg("Img/bg2.jpg");
        else updateDashboardBg("Img/bg3.jpg");
        renderPartnerCards(container);
    }
};

window.selectGender = function(gender, cardEl) {
    if (userGender === gender) {
        userGender = null;
        cardEl.classList.remove("selected");
        document.getElementById("btn_next").classList.add("disabled");
    } else {
        userGender = gender;
        document.querySelectorAll(".gender-card").forEach(function(el){ el.classList.remove("selected"); });
        cardEl.classList.add("selected");
        document.getElementById("btn_next").classList.remove("disabled");
    }
};

function updateDashboardBg(imageUrl) {
    var bgInfo = document.getElementById("dashboard_bg");
    if (bgInfo) {
        bgInfo.style.backgroundImage = imageUrl ? "url('" + imageUrl + "')" : "none";
    }
}

function renderPartnerCards(container) {
    var allChars = [{ id: "TETO_M", type: "Testosterone", name: "테토남" }, { id: "TETO_F", type: "Testosterone", name: "테토녀" }, { id: "EGEN_M", type: "Estrogen", name: "에겐남" }, { id: "EGEN_F", type: "Estrogen", name: "에겐녀" }];
    var targetSuffix = (userGender === "M") ? "_F" : "_M";
    var filtered = allChars.filter(function(char) { return char.id.endsWith(targetSuffix); });

    filtered.forEach(function(char) {
        var card = document.createElement("div");
        card.className = "character-card";
        if (selectedCharacter && selectedCharacter.id === char.id) card.classList.add("selected");
        card.onclick = function() { window.selectPartner(char, card); };
        card.ontouchend = function() { window.selectPartner(char, card); };
        var iconImg = (char.type === "Estrogen") ? "Img/IconEG.png" : "Img/IconTT.png";
        card.innerHTML = `<div class="card-image-placeholder"><img src="${iconImg}" style="height: 100px; width: auto; object-fit: contain;" /></div><div class="card-info"><h4>${char.name}</h4><p>(${char.type})</p></div>`;
        container.appendChild(card);
    });
}

window.selectPartner = function(charObj, cardEl) {
    if (selectedCharacter && selectedCharacter.id === charObj.id) {
        selectedCharacter = null;
        cardEl.classList.remove("selected");
        document.getElementById("btn_next").classList.add("disabled");
    } else {
        selectedCharacter = charObj;
        document.querySelectorAll(".character-card").forEach(function(el){ el.classList.remove("selected"); });
        cardEl.classList.add("selected");
        document.getElementById("btn_next").classList.remove("disabled");
    }
};

function showProfileView() {
    document.getElementById("title_profile").innerText = ""; 
    var bgMap = { TETO_M: "Img/bg4.jpg", TETO_F: "Img/bg5.jpg", EGEN_M: "Img/bg6.jpg", EGEN_F: "Img/bg7.jpg" };
    if (selectedCharacter && bgMap[selectedCharacter.id]) {
        updateDashboardBg(bgMap[selectedCharacter.id]);
    }
}

// [수정된 함수] 캐릭터별 씬 이동 로직 추가
window.startRealTour = function() {

    // 1. 캐릭터 ID와 이동할 씬 이름 매핑 (★본인의 씬 이름으로 수정 필요★)
    var sceneMapping = {
        'TETO_M': 'scene_TMLobby',    // 테토남 선택 시 이동할 씬 이름
        'TETO_F': 'scene_TFLobby',  // 테토녀 선택 시 이동할 씬 이름
        'EGEN_M': 'scene_EMLobby',    // 에겐남 선택 시 이동할 씬 이름
        'EGEN_F': 'scene_EFLobby'   // 에겐녀 선택 시 이동할 씬 이름
    };

    // 2. 선택된 캐릭터에 맞는 씬 이름 가져오기
    var targetScene = sceneMapping[selectedCharacter.id];

    // 3. krpano 로그 출력 및 씬 로드
    if (targetScene) {
        krpano.call("trace('Load Scene: " + targetScene + " (Character: " + selectedCharacter.name + ")');");

        // 씬 로드 (loadscene(씬이름, null, MERGE, 블렌드효과))
        krpano.call("loadscene(" + targetScene + ", null, MERGE, BLEND(1.0, easeInCubic));");
    } else {
        krpano.call("trace('Error: 씬 이름이 매핑되지 않았습니다. ID: " + selectedCharacter.id + "');");
        // 테스트용: 매핑된 씬이 없으면 기본 씬으로 이동하려면 아래 주석 해제
        // krpano.call("loadscene(scene_default, null, MERGE, BLEND(1.0));");
    }

    // 4. UI 페이드 아웃 및 제거 (기존 로직 유지)
    var panel = document.getElementById("dashboard_panel");
    var backdrop = document.getElementById("global_backdrop");

    if (panel) panel.style.opacity = "0";
    if (backdrop) backdrop.style.opacity = "0";

    setTimeout(function() {
        if (panel) panel.style.display = "none";
        if (backdrop) backdrop.style.display = "none";
    }, FADE_DURATION_MS);
};

window.handleBack = function() {
    if (currentStep > 1) showSelectionStep(currentStep - 1);
};
window.handleNext = function() {
    if (currentStep === STEP_START) showSelectionStep(STEP_INTRO_VIDEO);
    else if (currentStep === STEP_INTRO_VIDEO) showSelectionStep(STEP_GENDER);
    else if (currentStep === STEP_GENDER && userGender) showSelectionStep(STEP_PARTNER);
    else if (currentStep === STEP_PARTNER && selectedCharacter) showSelectionStep(STEP_PROFILE);
};

// 초기 실행
showSelectionStep(1);
